+      mimeType: mimeTypeForImageFormat(format) ?? 'image/png',
+      base64: base64Encode(bytes),
+      width: image.width,
+      height: image.height,
+      resized: false,
+      outputWidth: image.width,
+      outputHeight: image.height,
