    if (drawHeight > cell) drawHeight = cell;
    final tile = source.width == drawWidth && source.height == drawHeight
        ? source
        : copyResize(
            source,
            width: drawWidth,
            height: drawHeight,
            interpolation: Interpolation.cubic,
